<?php require_once 'db.php'; $page_title='Cake Menu'; $term=trim($_GET['q']??''); $category=trim($_GET['category']??''); $sql="SELECT * FROM cakes WHERE stock>0"; $args=[]; if($term!==''){$sql.=" AND (name LIKE ? OR flavour LIKE ?)";$args[]="%$term%";$args[]="%$term%";} if($category!==''){$sql.=" AND category=?";$args[]=$category;} $q=db()->prepare($sql);$q->execute($args);$items=$q->fetchAll(); include 'header.php'; ?>
<section class="section"><div class="eyebrow">THE CAKE MENU</div><h1 style="font-size:3rem">Pick your happy.</h1><form class="searchbar" method="get"><input name="q" placeholder="Search cake or flavour" value="<?= h($term) ?>"><select name="category"><option value="">All occasions</option><?php foreach(db()->query("SELECT DISTINCT category FROM cakes") as $c): ?><option <?= $category===$c['category']?'selected':'' ?>><?= h($c['category']) ?></option><?php endforeach; ?></select><button class="btn">Filter cakes</button></form><div class="grid" style="margin-top:28px"><?php foreach($items as $it): ?><article class="card"><div class="card-top">🍰</div><div class="card-body"><span class="tag"><?= h($it['category']) ?> · <?= h($it['flavour']) ?></span><h3><?= h($it['name']) ?></h3><p class="muted"><?= h($it['description']) ?></p><div class="price">₹<?= number_format($it['price'],0) ?></div><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><button class="btn" name="add">Add to cart</button></form></div></article><?php endforeach; ?></div></section><?php include 'footer.php'; ?>